/* ============================================================
   Textes dans la langue de l'élève (fr) pour data/core/grammar-reference.js
   Les clés renvoient aux id de la couche neutre ; les tableaux se
   joignent par index, leur longueur doit donc correspondre à core.
   Vérifié par scripts/parity.mjs.

   Les notes contrastives sont écrites contre le français, pas
   traduites du polonais : le point de comparaison change avec la
   langue du lecteur. Entre deux langues romanes, une bonne moitié
   des avertissements devient « ça, tu l'as déjà ».
   ============================================================ */
LINGUAI.addStrings("fr", {
  "refsec:titles": [
    "Noms et articles",
    "Adjectifs",
    "Pronoms",
    "Verbes — l'indicatif",
    "Verbes — subjonctif et conditionnel",
    "Impératif, formes non finies, le passif",
    "Prépositions, adverbes, connecteurs",
    "Syntaxe et texte"
  ],
  "ref:g-nome-genere": {
    title: "Le genre du nom",
    sub: "masculin et féminin, terminaisons -o / -a / -e",
    body: "<p>L'italien n'a pas de neutre : tout nom est masculin ou féminin, objets compris. Tu pars avec le système déjà en place, puisque le français fonctionne pareil. Le danger n'est pas la catégorie, ce sont les mots précis où les deux langues ne tombent pas d'accord.</p><h4>Trois schémas</h4><ul><li><b>-o</b> → masculin : <em>il libro, il tavolo</em>. Exceptions : <em>la mano, la radio, la foto, la moto</em> — les mêmes qu'en français, et pour la même raison (abréviations ou féminins latins).</li><li><b>-a</b> → féminin : <em>la casa, la porta</em>. Exceptions d'origine grecque : <em>il problema, il programma, il tema, il sistema, il clima</em>, comme « le problème » en français.</li><li><b>-e</b> → masculin <i>ou</i> féminin : <em>il fiore</em> mais <em>la chiave</em>. C'est la classe que le français n'a pas, et le genre s'apprend avec le mot.</li></ul><h4>Terminaisons qui trahissent le genre</h4><ul><li><b>-zione, -sione, -tà, -tù, -ice</b> sont toujours féminines : <em>la stazione, la città, la virtù, l'attrice</em>.</li><li><b>-ore, -ame, -ume</b> sont en général masculines : <em>il colore, il bestiame, il costume</em>.</li><li>Les emprunts prennent le genre du mot qu'ils remplacent : <em>il computer</em> (calcolatore), <em>la mail</em> (posta).</li></ul><p class='callout callout--trap'>Ceux qui ne coïncident pas avec le français, à mémoriser un par un : <em>il fiore</em> (la fleur), <em>il mare</em> (la mer), <em>il dente</em> (la dent), <em>la sera</em> (le soir), <em>il minuto</em> (la minute), <em>l'arte</em> est féminin comme en français mais <em>il colore</em> est masculin là où « la couleur » ne l'est pas.</p>"
  },
  "ref:g-nome-plurale": {
    title: "Le pluriel",
    sub: "-i, -e et les invariables",
    body: "<p>Le pluriel change la terminaison, il n'ajoute pas de lettre muette. <b>Il n'y a pas de -s du pluriel</b>, et surtout il s'entend : en français le pluriel est porté par l'article, en italien il est porté par le mot lui-même.</p><div class='table-wrap'><table class='gt'><thead><tr><th>singulier</th><th>pluriel</th><th>exemple</th></tr></thead><tbody><tr><td>-o (m)</td><td class='it'>-i</td><td>il libro → i libri</td></tr><tr><td>-a (f)</td><td class='it'>-e</td><td>la casa → le case</td></tr><tr><td>-a (m)</td><td class='it'>-i</td><td>il problema → i problemi</td></tr><tr><td>-e (m/f)</td><td class='it'>-i</td><td>il fiore → i fiori ; la chiave → le chiavi</td></tr></tbody></table></div><h4>Aucun changement</h4><p>Les mots accentués sur la dernière voyelle (<em>la città, il caffè</em>), les emprunts (<em>il bar, lo sport</em>), les mots abrégés (<em>la foto, il cinema</em>) et les monosyllabes (<em>il re</em>). Seul l'article indique le nombre — la situation habituelle du français.</p><h4>Orthographe</h4><ul><li><b>-co / -go</b> : accent sur l'avant-dernière syllabe → <em>-chi / -ghi</em> (<em>il fuoco → i fuochi</em>) ; accent plus tôt → <em>-ci / -gi</em> (<em>il medico → i medici</em>).</li><li><b>-ca / -ga</b> : toujours <em>-che / -ghe</em> (<em>l'amica → le amiche</em>).</li><li><b>-cia / -gia</b> : le i reste après une voyelle (<em>la camicia → le camicie</em>), tombe après une consonne (<em>l'arancia → le arance</em>).</li></ul>"
  },
  "ref:g-articolo-det": {
    title: "L'article défini",
    sub: "il, lo, la, l', i, gli, le",
    body: "<p>La forme dépend du genre, du nombre et du <b>premier son</b> du mot suivant. Le français a quatre formes (<em>le, la, les, l'</em>), l'italien en a sept, et l'élision n'est qu'une partie de l'histoire.</p><div class='table-wrap'><table class='gt'><thead><tr><th>contexte</th><th>sing.</th><th>plur.</th></tr></thead><tbody><tr><td>m. + consonne</td><td class='it'>il</td><td>i</td></tr><tr><td>m. + s+cons., z, gn, ps, x, y</td><td class='it'>lo</td><td>gli</td></tr><tr><td>m. + voyelle</td><td class='it'>l'</td><td>gli</td></tr><tr><td>f. + consonne</td><td class='it'>la</td><td>le</td></tr><tr><td>f. + voyelle</td><td class='it'>l'</td><td>le</td></tr></tbody></table></div><p>L'article s'accorde avec ce qui vient <b>immédiatement après lui</b>, pas avec le nom : <em>lo studente</em>, mais <em>il bravo studente</em>. C'est le même réflexe que l'élision française devant voyelle, poussé plus loin.</p><h4>Là où l'italien en met et le français aussi</h4><ul><li>devant les pays, régions, fleuves, montagnes : <em>l'Italia, la Toscana, il Po</em> — comme « la France », « la Loire » ; pas devant les villes, comme en français</li><li>avec les noms pris au sens général : <em>mi piace il caffè</em>, « j'aime le café »</li><li>avec les jours pour dire « tous les » : <em>il lunedì</em> = le lundi</li></ul><p class='callout callout--trap'>La différence, c'est le possessif : <em>il mio libro</em>, là où le français dit « mon livre » sans article. Oublier cet article est l'erreur qui trahit le plus vite un francophone.</p>"
  },
  "ref:g-articolo-indet": {
    title: "Articles indéfini et partitif",
    sub: "un, uno, una, un' et del, della, dei…",
    body: "<p><b>Indéfini</b> : <em>un</em> (m + consonne et voyelle), <em>uno</em> (m + s+cons., z), <em>una</em> (f + consonne), <em>un'</em> (f + voyelle).</p><p class='callout callout--trap'><b>un amico</b> sans apostrophe (un garçon) contre <b>un'amica</b> avec apostrophe (une fille). C'est l'apostrophe qui porte ici le genre, et elle saute facilement.</p><p><b>Partitif</b> (di + article défini) : <em>del pane</em>, <em>dell'acqua</em>, <em>delle mele</em>. Le français a exactement la même chose — « du pain », « de l'eau », « des pommes » — formée de la même manière, avec de + article. C'est un des rares points où la traduction mot à mot marche.</p><p>Il disparaît en général à la forme négative : <em>non ho pane</em>, comme « je n'ai pas de pain ».</p><p>Il n'y a pas de pluriel de l'article indéfini : le partitif s'en charge, <em>un libro → dei libri</em>.</p>"
  },
  "ref:g-articolo-omissione": {
    title: "Quand il n'y a PAS d'article",
    sub: "omissions et expressions figées",
    body: "<ul><li>après <em>essere</em> avec un métier ou une nationalité : <em>sono medico, sono francese</em> — exactement le « je suis médecin » français</li><li>devant les noms de villes et de petites îles : <em>vado a Roma, a Capri</em></li><li>devant les démonstratifs et les interrogatifs : <em>questo libro, quanti anni hai?</em></li><li>devant un seul membre de la famille non modifié, avec un possessif : <em>mia madre</em>, mais <em>le mie sorelle</em></li><li>dans les expressions figées : <em>andare in vacanza, cercare lavoro, avere fame, a casa, in ufficio</em></li><li>après <em>di</em> pour la matière et l'appartenance : <em>un tavolo di legno, la casa di Marco</em></li></ul><p>En <b>C1</b>, on rencontre des tournures qui suppriment l'article devant le possessif : <em>a mio parere, a sua insaputa, a mio nome</em>.</p>"
  },
  "ref:g-nome-avanzato": {
    title: "Pluriels difficiles",
    sub: "formes doubles et composés",
    body: "<h4>Deux pluriels, deux sens</h4><p>Une douzaine de noms ont deux pluriels de sens différents : <em>l'osso → gli ossi</em> (des os séparés, ceux qu'on donne au chien) et <em>le ossa</em> (le squelette) ; <em>il filo → i fili</em> (des fils, des câbles) et <em>le fila</em> (les fils d'une intrigue) ; <em>il frutto → i frutti</em> (les fruits au sens de résultats) et <em>la frutta</em> (les fruits qu'on mange) ; <em>il braccio → le braccia</em> (les bras du corps) et <em>i bracci</em> (les bras d'une grue).</p><h4>Composés</h4><ul><li>invariables : <em>il doposcuola → i doposcuola</em></li><li>le second élément change : <em>il cavolfiore → i cavolfiori</em>, <em>il capolavoro → i capolavori</em>, <em>l'asciugamano → gli asciugamani</em></li><li>le premier change : <em>il capofamiglia → i capifamiglia</em>, <em>il fico d'India → i fichi d'India</em> — le principe des « chefs de gare » français, où le pluriel va sur le noyau</li><li>les deux changent : <em>la cassaforte → le casseforti</em>, <em>il bassofondo → i bassifondi</em></li></ul>"
  },
  "ref:g-agg-accordo": {
    title: "L'accord de l'adjectif",
    sub: "quatre terminaisons et deux",
    body: "<p>L'adjectif s'accorde en genre et en nombre et se place normalement <b>après</b> le nom. Le français fait pareil, donc l'automatisme est déjà là — sauf que l'accord italien s'entend, alors que le français l'écrit souvent sans le prononcer.</p><div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>m. sing.</th><th>f. sing.</th><th>m. plur.</th><th>f. plur.</th></tr></thead><tbody><tr><td>4 terminaisons</td><td class='it'>rosso</td><td>rossa</td><td>rossi</td><td>rosse</td></tr><tr><td>2 terminaisons</td><td class='it'>verde</td><td>verde</td><td>verdi</td><td>verdi</td></tr><tr><td>invariable</td><td class='it'>blu</td><td>blu</td><td>blu</td><td>blu</td></tr></tbody></table></div><p>Invariables : <em>blu, rosa, viola, beige, marrone</em> (ce dernier s'accorde à l'oral) et les emprunts : <em>chic, snob, super</em>. Même logique que « des yeux marron » en français.</p><p>Avec un groupe mixte, le masculin l'emporte : <em>Marco e Anna sono italiani</em>.</p>"
  },
  "ref:g-agg-posizione": {
    title: "Où se place l'adjectif",
    sub: "avant ou après le nom",
    body: "<p>Après le nom par défaut. Une poignée d'adjectifs fréquents et non distinctifs passent devant : <em>bello, buono, grande, piccolo, giovane, vecchio, nuovo, bravo</em>.</p><p>Le déplacement change le sens, et le français fait exactement la même chose : « un grand homme » n'est pas « un homme grand », « un ancien ami » n'est pas « un ami ancien ». La liste italienne recoupe presque la française, donc ton intuition sert :</p><div class='table-wrap'><table class='gt'><thead><tr><th>avant</th><th>après</th></tr></thead><tbody><tr><td class='it'>un vecchio amico (un vieil ami, de longue date)</td><td>un amico vecchio (un ami âgé)</td></tr><tr><td class='it'>un grande uomo (un grand homme)</td><td>un uomo grande (un homme grand)</td></tr><tr><td class='it'>un buon medico (compétent)</td><td>un medico buono (quelqu'un de bon)</td></tr><tr><td class='it'>una certa informazione (une certaine information)</td><td>un'informazione certa (une information sûre)</td></tr><tr><td class='it'>un alto magistrato (haut placé)</td><td>un magistrato alto (grand de taille)</td></tr></tbody></table></div><p><b>Bello</b> et <b>quello</b> devant un nom se comportent comme l'article : <em>bel libro, bello studente, begli amici, bella casa</em>.</p>"
  },
  "ref:g-agg-gradi": {
    title: "Comparatifs et superlatifs",
    sub: "comparativo et superlativo",
    body: "<h4>Comparatif</h4><ul><li>supériorité : <em>Anna è <b>più</b> alta <b>di</b> Marco</em> ; devant un verbe, un adjectif ou une préposition on emploie <b>che</b> — <em>è più facile parlare che scrivere</em>. Le français dit toujours « que », donc l'alternance di/che est à apprendre.</li><li>infériorité : <em><b>meno</b> caro <b>di</b>…</em></li><li>égalité : <em>tanto… quanto</em>, <em>così… come</em></li></ul><h4>Superlatif</h4><ul><li>relatif : <em>il <b>più</b> bello <b>della</b> città</em></li><li>absolu : <em>bell<b>issimo</b></em>, ou <em>molto bello</em>. Le français doit passer par « très » ou « extrêmement » ; l'italien a une terminaison pour ça.</li></ul><h4>Formes irrégulières</h4><div class='table-wrap'><table class='gt'><thead><tr><th>base</th><th>comparatif</th><th>superlatif</th></tr></thead><tbody><tr><td>buono</td><td class='it'>migliore</td><td>ottimo / il migliore</td></tr><tr><td>cattivo</td><td class='it'>peggiore</td><td>pessimo / il peggiore</td></tr><tr><td>grande</td><td class='it'>maggiore</td><td>massimo</td></tr><tr><td>piccolo</td><td class='it'>minore</td><td>minimo</td></tr></tbody></table></div><p>Les mêmes paires que « meilleur / pire » en français, y compris l'existence des deux séries (régulière et savante). En <b>C1</b>, ajoute les intensifs familiers (<em>magra magra</em>), les préfixes (<em>arcicontento, straricco, iperattivo</em>), les locutions (<em>stanco morto, ubriaco fradicio, buono come il pane</em>) et les formes en <em>-errimo</em> (<em>acerrimo, celeberrimo</em>).</p>"
  },
  "ref:g-possessivi": {
    title: "Les possessifs",
    sub: "mio, tuo, suo… et le piège de la famille",
    body: "<p>Le possessif s'accorde avec <b>l'objet possédé</b>, pas avec le possesseur. Le français fait déjà ça : « sa sœur » vaut pour lui comme pour elle, exactement comme <em>sua sorella</em>. Rien à désapprendre.</p><div class='table-wrap'><table class='gt'><thead><tr><th>personne</th><th>m. sing.</th><th>f. sing.</th><th>m. plur.</th><th>f. plur.</th></tr></thead><tbody><tr><td>io</td><td class='it'>mio</td><td>mia</td><td>miei</td><td>mie</td></tr><tr><td>tu</td><td class='it'>tuo</td><td>tua</td><td>tuoi</td><td>tue</td></tr><tr><td>lui/lei</td><td class='it'>suo</td><td>sua</td><td>suoi</td><td>sue</td></tr><tr><td>noi</td><td class='it'>nostro</td><td>nostra</td><td>nostri</td><td>nostre</td></tr><tr><td>voi</td><td class='it'>vostro</td><td>vostra</td><td>vostri</td><td>vostre</td></tr><tr><td>loro</td><td class='it'>loro</td><td>loro</td><td>loro</td><td>loro</td></tr></tbody></table></div><p class='callout callout--trap'>Ce qui est nouveau : le possessif italien <b>prend l'article</b>. <em>Il mio libro</em>, pas « mio libro ». Le français le supprime (« mon livre »), et l'oublier en italien est l'erreur la plus tenace chez un francophone.</p><p><b>Sans article</b> devant un seul membre de la famille non modifié : <em>mia madre, tuo fratello</em>. L'article revient au pluriel (<em>i miei genitori</em>), avec un diminutif (<em>la mia sorellina</em>), avec un modificateur (<em>la mia sorella maggiore</em>) ou avec <em>loro</em> (<em>la loro madre</em>).</p><p>Quand le contexte ne suffit pas, l'italien dit <em>di lui / di lei</em>.</p>"
  },
  "ref:g-pron-soggetto": {
    title: "Les pronoms sujets",
    sub: "io, tu, lui… et pourquoi on les omet",
    body: "<p><em>io, tu, lui/lei, noi, voi, loro</em>. On les omet presque toujours, la terminaison suffit à dire qui parle.</p><p class='callout callout--trap'>C'est ici que le français ne sert pas : il exige le sujet dans chaque phrase, y compris impersonnelle (« il pleut »). En italien, mettre le pronom sans raison sonne insistant, et <em>piove</em> se dit sans rien devant. Le réflexe français d'écrire le sujet doit être désactivé.</p><p>On les emploie pour le <b>contraste</b> (<em>io lavoro, tu dormi</em>), après <em>anche</em>, <em>neanche</em>, <em>nemmeno</em>, et dans les réponses brèves (<em>Chi è? — Io.</em>).</p><p><b>Lei</b> avec majuscule est la forme de politesse, pour les hommes comme pour les femmes, avec un verbe à la troisième personne du singulier. Ce n'est pas le « vous » français : c'est une troisième personne, et c'est le point qui déroute le plus. Au pluriel, l'usage moderne est <em>voi</em> ; <em>Loro</em> ne survit que dans un registre très formel.</p><p>Les formes <em>egli, ella, esso, essi</em> appartiennent à l'italien écrit et littéraire.</p>"
  },
  "ref:g-pron-diretti": {
    title: "Pronoms compléments directs",
    sub: "mi, ti, lo, la, ci, vi, li, le",
    body: "<p>Ils remplacent le complément construit sans préposition (qui ? quoi ?) et se placent <b>devant</b> le verbe conjugué. Le français fait pareil, donc la position ne pose pas de problème.</p><div class='table-wrap'><table class='gt'><thead><tr><th>sens</th><th>atone</th><th>tonique</th></tr></thead><tbody><tr><td>me</td><td class='it'>mi</td><td>me</td></tr><tr><td>te</td><td class='it'>ti</td><td>te</td></tr><tr><td>le (lui)</td><td class='it'>lo</td><td>lui</td></tr><tr><td>la (elle)</td><td class='it'>la</td><td>lei</td></tr><tr><td>nous</td><td class='it'>ci</td><td>noi</td></tr><tr><td>vous</td><td class='it'>vi</td><td>voi</td></tr><tr><td>les (m)</td><td class='it'>li</td><td>loro</td></tr><tr><td>les (f)</td><td class='it'>le</td><td>loro</td></tr></tbody></table></div><p><b>Accord du participe.</b> Aux temps composés avec <em>avere</em>, le participe s'accorde avec le pronom direct qui précède : <em>L'ho vista</em>, <em>Li ho comprati</em>, <em>Le ho salutate</em>. C'est exactement la règle française du COD antéposé — « je l'ai vue », « je les ai achetés ». La différence : en italien l'accord s'entend.</p><p>Avec un infinitif après un verbe modal, deux places sont possibles : <em>ti posso aiutare</em> = <em>posso aiutarti</em>, comme « je peux t'aider ».</p>"
  },
  "ref:g-pron-indiretti": {
    title: "Pronoms compléments indirects",
    sub: "mi, ti, gli, le, ci, vi, gli",
    body: "<p>Ils répondent à « à qui ? » et remplacent <em>a + personne</em> : <em>Telefono a Marco → Gli telefono</em>.</p><p>Formes : <em>mi, ti, <b>gli</b> (à lui), <b>le</b> (à elle), ci, vi, <b>gli</b> (à eux)</em>. En registre formel, « à eux » se dit <em>loro</em>, placé après le verbe : <em>Telefono loro</em>.</p><p class='callout callout--trap'>L'italien distingue <em>gli</em> (à lui) de <em>le</em> (à elle), là où le français a un seul « lui » pour les deux. C'est l'inverse du direct, où le français sépare le/la et l'italien aussi : c'est donc une distinction de plus à tenir.</p><p><b>Gli</b> est à la fois article (« gli amici ») et pronom (« gli parlo »). La position dans la phrase les sépare.</p><p>Le participe <b>ne s'accorde pas</b> avec un pronom indirect : <em>Le ho parlato</em>, jamais « parlata ». Même règle qu'en français.</p><p>Verbes qui demandent un complément indirect en italien : <em>telefonare a, rispondere a, chiedere a, credere a, piacere a, dispiacere a</em>. Le recoupement avec le français est large.</p>"
  },
  "ref:g-pron-combinati": {
    title: "Pronoms groupés",
    sub: "me lo, te la, glielo, ce ne…",
    body: "<p>Quand deux pronoms se rencontrent, l'indirect passe devant et son <em>-i</em> devient <em>-e</em>. L'ordre est celui du français (« tu me le donnes »), ce qui règle la moitié du problème.</p><div class='table-wrap'><table class='gt'><thead><tr><th></th><th>lo</th><th>la</th><th>li</th><th>le</th><th>ne</th></tr></thead><tbody><tr><td>mi</td><td class='it'>me lo</td><td>me la</td><td>me li</td><td>me le</td><td>me ne</td></tr><tr><td>ti</td><td class='it'>te lo</td><td>te la</td><td>te li</td><td>te le</td><td>te ne</td></tr><tr><td>gli / le</td><td class='it'>glielo</td><td>gliela</td><td>glieli</td><td>gliele</td><td>gliene</td></tr><tr><td>ci</td><td class='it'>ce lo</td><td>ce la</td><td>ce li</td><td>ce le</td><td>ce ne</td></tr><tr><td>vi</td><td class='it'>ve lo</td><td>ve la</td><td>ve li</td><td>ve le</td><td>ve ne</td></tr></tbody></table></div><p class='callout callout--trap'>Attention à l'ordre inverse : le français dit « je le lui donne » (direct puis indirect à la 3<sup>e</sup> personne), l'italien garde toujours l'indirect en tête, <em>glielo do</em>. C'est le seul endroit où l'ordre des deux langues diverge.</p><p><b>Glielo</b> couvre à la fois « à lui », « à elle » et « à eux », et s'écrit en un seul mot.</p>"
  },
  "ref:g-ci-ne": {
    title: "Ci et ne",
    sub: "deux particules qui portent la moitié de la langue",
    body: "<p>Bonne nouvelle : ce sont <b>y</b> et <b>en</b>. Le français les a gardés là où l'anglais et l'espagnol les ont perdus, et le recouvrement est presque parfait. Là où tu dirais « j'y vais » ou « j'en veux trois », l'italien dit <em>ci vado</em> et <em>ne voglio tre</em>.</p><h4>CI = y</h4><ul><li>lieu : <em>Vai a Roma? — Sì, ci vado domani.</em></li><li>remplace <em>a + chose</em> : <em>Pensi all'esame? — Ci penso sempre.</em> (j'y pense)</li><li>dans <em>c'è / ci sono</em> — le « il y a » français</li><li>dans les verbes pronominaux : <em>farcela</em> (y arriver), <em>volerci</em> (falloir), <em>metterci</em> (mettre du temps), <em>entrarci</em> (avoir un rapport)</li></ul><h4>NE = en</h4><ul><li>partie d'un tout : <em>Quante mele vuoi? — Ne voglio tre.</em> (j'en veux trois)</li><li>remplace <em>di + chose/personne</em> : <em>Parliamo del film? — Ne parliamo domani.</em> (on en parle)</li><li>provenance : <em>Vieni dal lavoro? — Sì, ne vengo adesso.</em> (j'en viens)</li><li>dans les verbes : <em>andarsene</em> (s'en aller), <em>fregarsene</em> (s'en ficher), <em>accorgersene</em></li></ul><p>Avec <em>ne</em> aux temps composés, le participe s'accorde en nombre : <em>Ne ho comprate tre.</em> Le français ne le fait pas avec « en » : c'est la seule vraie divergence de ce chapitre.</p>"
  },
  "ref:g-relativi": {
    title: "Les pronoms relatifs",
    sub: "che, cui, il quale, chi",
    body: "<ul><li><b>che</b> — invariable, sujet et complément direct à la fois : <em>il libro che leggo</em>. Il couvre « qui » et « que » d'un seul mot, ce qui est plus simple qu'en français.</li><li><b>cui</b> — après une préposition : <em>la persona <b>a cui</b> penso</em>, <em>la città <b>in cui</b> vivo</em>. Là où le français dit « à qui », « dans laquelle », l'italien met <em>cui</em> tout court.</li><li>avec un article, <em>cui</em> marque la possession : <em>il ragazzo <b>la cui</b> madre è medico</em> — le « dont » français, mais l'article s'accorde avec l'objet possédé, ce que « dont » ne fait pas.</li><li><b>il quale / la quale / i quali / le quali</b> — variante formelle, utile pour lever une ambiguïté, comme « lequel ».</li><li><b>chi</b> — « celui qui », personnes seulement, toujours singulier : <em>Chi dorme non piglia pesci.</em></li></ul><p>En <b>C1</b>, ajoute le relatif neutre : <em><b>il che</b> mi sembra strano</em> (« ce qui »), <em>la ragione <b>per cui</b>…</em></p>"
  },
  "ref:g-si": {
    title: "Toutes les valeurs de SI",
    sub: "réfléchi, réciproque, impersonnel, passif",
    body: "<p>C'est le « se » et le « on » français réunis dans une seule particule. La répartition des valeurs est très proche ; ce qui change, c'est un détail d'accord et la forme <em>ci si</em>.</p><div class='table-wrap'><table class='gt'><thead><tr><th>valeur</th><th>exemple</th><th>note</th></tr></thead><tbody><tr><td>réfléchi</td><td class='it'>Marco si lava.</td><td>il se lave</td></tr><tr><td>réciproque</td><td class='it'>Si salutano ogni giorno.</td><td>l'un l'autre</td></tr><tr><td>impersonnel</td><td class='it'>In Italia si mangia bene.</td><td>« on mange bien »</td></tr><tr><td>passif (passivante)</td><td class='it'>Qui si vendono panini.</td><td>« ici se vendent »</td></tr><tr><td>instruction</td><td class='it'>Il volante si tiene così.</td><td>voilà comment on fait</td></tr><tr><td>« nous » toscan</td><td class='it'>Stasera noi si va al cinema.</td><td>régional</td></tr></tbody></table></div><p>Le <em>si</em> impersonnel avec un verbe réfléchi donne <b>ci si</b> : <em>ci si alza presto</em>, là où le français dit « on se lève tôt ». Aux temps composés, le <em>si</em> impersonnel prend toujours <em>essere</em> et le participe finit en <em>-i</em> : <em>si è mangiato bene</em>, mais <em>si è stati contenti</em>.</p>"
  },
  "ref:g-verbi-pronominali": {
    title: "Les verbes pronominaux",
    sub: "farcela, cavarsela, prendersela",
    body: "<p>Une famille de verbes dont le sens ne se déduit pas des morceaux. Le français a la même chose avec « s'en aller », « s'en ficher », « s'y prendre », « l'emporter » : le pronom soudé au verbe, et un sens qui n'est pas la somme des parties.</p><div class='table-wrap'><table class='gt'><thead><tr><th>forme</th><th>sens</th><th>exemple</th></tr></thead><tbody><tr><td class='it'>farcela</td><td>y arriver</td><td>Non ce la faccio più.</td></tr><tr><td class='it'>cavarsela</td><td>s'en sortir</td><td>Me la cavo con l'italiano.</td></tr><tr><td class='it'>prendersela</td><td>se vexer</td><td>Non te la prendere.</td></tr><tr><td class='it'>andarsene</td><td>s'en aller</td><td>Me ne vado.</td></tr><tr><td class='it'>fregarsene</td><td>s'en ficher</td><td>Se ne frega di tutto.</td></tr><tr><td class='it'>volerci</td><td>falloir</td><td>Ci vogliono due ore.</td></tr><tr><td class='it'>metterci</td><td>mettre (du temps)</td><td>Ci metto un'ora.</td></tr><tr><td class='it'>avercela con</td><td>en vouloir à</td><td>Ce l'ha con me.</td></tr></tbody></table></div><p>Aux temps composés ils prennent <em>essere</em>, et le participe s'accorde avec <em>la</em> : <em>me la sono cavata</em>, <em>ce l'ho fatta</em>.</p>"
  },
  "ref:g-presente": {
    title: "Le présent",
    sub: "trois conjugaisons et le schéma -isc-",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>personne</th><th>-are</th><th>-ere</th><th>-ire</th><th>-ire (-isc-)</th></tr></thead><tbody><tr><td>io</td><td class='it'>parlo</td><td>leggo</td><td>dormo</td><td>capisco</td></tr><tr><td>tu</td><td class='it'>parli</td><td>leggi</td><td>dormi</td><td>capisci</td></tr><tr><td>lui/lei</td><td class='it'>parla</td><td>legge</td><td>dorme</td><td>capisce</td></tr><tr><td>noi</td><td class='it'>parliamo</td><td>leggiamo</td><td>dormiamo</td><td>capiamo</td></tr><tr><td>voi</td><td class='it'>parlate</td><td>leggete</td><td>dormite</td><td>capite</td></tr><tr><td>loro</td><td class='it'>parlano</td><td>leggono</td><td>dormono</td><td>capiscono</td></tr></tbody></table></div><h4>Ce qu'il couvre</h4><p>Trois conjugaisons comme en français, et la même répartition d'emplois : l'instant présent, l'habitude, le futur proche avec un repère temporel (<em>domani parto</em>, « demain je pars »), les vérités générales, le présent de narration.</p><p>Ce que le français n'a pas, c'est le groupe <b>-isc-</b> : certains verbes en <em>-ire</em> insèrent <em>-isc-</em> aux trois premières personnes et à la troisième du pluriel (<em>capisco, capisci, capisce, capiamo, capite, capiscono</em>). C'est l'équivalent lointain de l'infixe de « finir → finissons », mais il ne se place pas aux mêmes personnes : à retenir verbe par verbe.</p><p>Changements orthographiques : <em>-care/-gare</em> ajoutent un h (<em>cerchi, paghi</em>) là où le français écrit qu/gu ; <em>-ciare/-giare/-iare</em> perdent le i (<em>mangi, studi</em>).</p>"
  },
  "ref:g-passato-prossimo": {
    title: "Passato prossimo",
    sub: "avere ou essere, le participe, l'accord",
    body: "<p>Le passé de la conversation : <b>avere ou essere au présent + participe passé</b>. C'est le passé composé français, structure comprise.</p><h4>Participes réguliers</h4><p><em>-are → -ato</em> (parlato), <em>-ere → -uto</em> (creduto), <em>-ire → -ito</em> (finito).</p><h4>Le choix de l'auxiliaire</h4><p>C'est ici que le français donne son plus gros avantage : lui aussi partage entre « être » et « avoir », et la liste des verbes est presque la même. Là où un anglophone ou un hispanophone doit tout construire, tu n'as qu'à vérifier les écarts.</p><ul><li><b>avere</b> : verbes transitifs, ceux qui ont un complément direct — <em>ho mangiato la pizza</em></li><li><b>essere</b> : mouvement et changement d'état (<em>andare, venire, arrivare, partire, uscire, entrare, salire, scendere, tornare, nascere, morire, diventare, restare, rimanere, stare, essere, piacere, succedere, costare</em>) et tous les verbes réfléchis</li></ul><p class='callout callout--trap'>Les écarts à connaître : <em>essere</em> et <em>stare</em> se conjuguent avec <em>essere</em> (<em>sono stato</em>), là où le français dit « j'ai été » ; et <em>piacere</em>, <em>costare</em>, <em>succedere</em> prennent aussi <em>essere</em>. Inversement, <em>vivere</em> accepte les deux.</p><p>Avec <em>essere</em>, le participe s'accorde avec le sujet : <em>sono andato / sono andata / siamo andati / sono andate</em> — la règle française, mais audible.</p><h4>Participes irréguliers fréquents</h4><p><em>fare→fatto, dire→detto, vedere→visto, prendere→preso, mettere→messo, leggere→letto, scrivere→scritto, aprire→aperto, chiudere→chiuso, chiedere→chiesto, rispondere→risposto, essere→stato, nascere→nato, morire→morto, venire→venuto, rimanere→rimasto, vivere→vissuto, perdere→perso, offrire→offerto, scegliere→scelto, decidere→deciso, vincere→vinto, bere→bevuto</em>.</p>"
  },
  "ref:g-imperfetto": {
    title: "Imperfetto",
    sub: "description, habitude, arrière-plan",
    body: "<p>Pratiquement régulier partout : radical + <em>-vo, -vi, -va, -vamo, -vate, -vano</em>. Exceptions : <em>essere</em> (ero, eri, era…), <em>fare</em> (facevo), <em>dire</em> (dicevo), <em>bere</em> (bevevo).</p><p>C'est l'imparfait français, avec le même partage des tâches face au passé composé. Si tu distingues déjà « il pleuvait » de « il a cessé de pleuvoir », le critère est acquis : il ne reste qu'à changer de formes.</p><div class='table-wrap'><table class='gt'><thead><tr><th>imperfetto</th><th>passato prossimo</th></tr></thead><tbody><tr><td class='it'>description, arrière-plan</td><td>événement, un point</td></tr><tr><td class='it'>Pioveva e faceva freddo.</td><td>Ha smesso di piovere alle sei.</td></tr><tr><td class='it'>répété : da bambino andavo</td><td>achevé : ieri sono andato</td></tr><tr><td class='it'>durée sans bornes</td><td>durée bornée : ho lavorato per tre ore</td></tr></tbody></table></div><p>Emplois supplémentaires (B1) : la demande polie (<em>volevo un caffè</em>, comme « je voulais un café »), le récit de rêve, le style journalistique, et la condition irréelle à l'oral (<em>se lo sapevo, venivo</em>), calquée sur « si je savais, je venais ».</p>"
  },
  "ref:g-futuro": {
    title: "Futuro semplice et anteriore",
    sub: "projets, conjectures, antériorité",
    body: "<p>Radical de l'infinitif sans le <em>-e</em> final (en -are, a → e) + <em>-ò, -ai, -à, -emo, -ete, -anno</em> : <em>parlerò, prenderò, partirò</em>. C'est un futur synthétique, comme « je parlerai ».</p><p>Radicaux irréguliers : <em>essere→sar-, avere→avr-, andare→andr-, venire→verr-, volere→vorr-, potere→potr-, dovere→dovr-, sapere→sapr-, vedere→vedr-, bere→berr-, rimanere→rimarr-, tenere→terr-</em>.</p><h4>Ce qu'il fait</h4><ul><li>le futur : <em>l'anno prossimo andrò in Italia</em></li><li><b>une conjecture sur le présent</b> : <em>Che ore sono? — Saranno le tre.</em> Le français fait pareil : « il doit être trois heures », ou « ce sera lui ».</li><li>concession : <em>Sarà anche bravo, ma non mi piace.</em></li></ul><p class='callout callout--trap'>Le futur proche français (« je vais partir ») n'a pas d'équivalent grammaticalisé : l'italien emploie le présent avec un repère (<em>domani parto</em>) ou le futur simple. Traduire « je vais » par <em>vado a</em> est une faute.</p><p><b>Futuro anteriore</b> (avrò fatto / sarò andato) marque une action achevée avant une autre à venir : <em>Quando avrò finito, ti chiamo</em>, et la conjecture sur le passé : <em>Avrà perso il treno.</em></p>"
  },
  "ref:g-trapassato": {
    title: "Trapassato prossimo",
    sub: "le passé avant le passé",
    body: "<p>Imperfetto de <em>avere/essere</em> + participe : <em>avevo mangiato, ero andato</em>. C'est le plus-que-parfait français, forme pour forme et valeur pour valeur.</p><p>Il marque une action antérieure à une autre action passée : <em>Quando sono arrivato, il treno <b>era già partito</b>.</em></p><p>L'oral le remplace souvent par le passato prossimo, mais dans un récit écrit il est indispensable : c'est lui qui tient la chronologie.</p>"
  },
  "ref:g-passato-remoto": {
    title: "Passato remoto",
    sub: "récit, histoire, sud de l'Italie",
    body: "<p>Régulier : <em>-are</em> : ai, asti, ò, ammo, aste, arono ; <em>-ere</em> : ei/etti, esti, é/ette, emmo, este, erono/ettero ; <em>-ire</em> : ii, isti, ì, immo, iste, irono.</p><p>Beaucoup de verbes en -ere suivent le <b>schéma 1-3-3</b> : seules les formes io, lui/lei et loro sont irrégulières, le reste est régulier. <em>prendere → presi, prendesti, prese, prendemmo, prendeste, presero</em>.</p><h4>Quand on l'emploie</h4><ul><li>dans le récit littéraire et historique : <em>Dante nacque nel 1265</em> — c'est le passé simple français, même emploi, même registre</li><li>pour des faits lointains et clos, sans lien avec le présent</li><li>dans la langue parlée du sud, même pour hier ; dans le nord il n'existe presque plus</li></ul><p>Cette dernière ligne est la seule différence avec le français, où le passé simple a disparu de l'oral partout. En Sicile ou en Campanie, on l'entend au café.</p><p><b>Trapassato remoto</b> (<em>ebbi fatto</em>) n'apparaît qu'après une conjonction de temps dans les textes littéraires : <em>Appena ebbe finito, uscì.</em> — le passé antérieur français, avec la même rareté.</p>"
  },
  "ref:g-condizionale": {
    title: "Le conditionnel",
    sub: "vorrei, potrei, avrei voluto",
    body: "<p>Même radical que le futur + <em>-ei, -esti, -ebbe, -emmo, -este, -ebbero</em> : <em>parlerei, sarei, avrei, vorrei, potrei</em>. Formation identique à celle du français, où le conditionnel se bâtit aussi sur le radical du futur.</p><h4>Ce qu'il fait</h4><ul><li>demande polie : <em>Vorrei un caffè.</em> — de loin l'emploi le plus courant, le « je voudrais » français</li><li>conseil : <em>Dovresti riposare.</em></li><li>souhait : <em>Mi piacerebbe vederti.</em></li><li>information non confirmée dans la presse : <em>Il ministro sarebbe pronto a dimettersi.</em> Le français journalistique fait exactement pareil : « le ministre serait prêt à démissionner ».</li></ul><p><b>Condizionale passato</b> (<em>avrei fatto, sarei andato</em>) couvre la possibilité non réalisée (<em>sarei venuto, ma…</em>) et <b>le futur vu du passé</b> : <em>Ha detto che <b>sarebbe venuto</b></em>. Ici le français dit « il a dit qu'il viendrait » avec un conditionnel présent, et l'italien exige le <b>passé</b>. C'est la divergence qui résiste le plus longtemps.</p>"
  },
  "ref:g-congiuntivo-pres": {
    title: "Congiuntivo presente et passato",
    sub: "quand il s'impose et quand il ne s'impose pas",
    body: "<p>Terminaisons : <em>-are</em> → i, i, i, iamo, iate, ino ; <em>-ere/-ire</em> → a, a, a, iamo, iate, ano ; <em>-isc-</em> → isca, isca, isca, iamo, iate, iscano.</p><p>Bonne nouvelle : tu as un subjonctif vivant et tu l'emploies tous les jours. Il n'y a pas d'instinct à construire, seulement une liste de déclencheurs à ajuster — elle recoupe la française à peu près aux quatre cinquièmes.</p><p>Les trois premières personnes sont identiques, donc avec le congiuntivo on <b>ne supprime pas le pronom</b> : <em>penso che <b>tu</b> abbia ragione</em>. Le français n'a pas ce problème puisqu'il garde le sujet partout.</p><h4>Exige le subjonctif</h4><ul><li>opinion et supposition : <em>penso che, credo che, mi sembra che, immagino che</em></li><li>volonté et sentiment : <em>voglio che, spero che, temo che, mi dispiace che, sono contento che</em></li><li>tournures impersonnelles : <em>è necessario che, bisogna che, è possibile che, è strano che</em></li><li>conjonctions : <em>benché, sebbene, nonostante, affinché, perché (=pour que), purché, a meno che, prima che, senza che, come se</em></li><li>relatives négatives ou indéfinies : <em>cerco una persona che parli inglese</em></li></ul><p class='callout callout--trap'>Les deux écarts qui coûtent cher. Premier : <em>penso che</em>, <em>credo che</em> demandent le subjonctif en italien, alors que « je pense que » et « je crois que » prennent l'indicatif en français à la forme affirmative. Second : <em>spero che</em> veut le subjonctif, tandis que « j'espère que » prend l'indicatif. Ce sont les deux verbes les plus fréquents de la liste.</p><h4>Ne l'exige pas</h4><p>La certitude : <em>so che, è certo che, è vero che, siccome, perché (=parce que)</em>. Avec le même sujet dans les deux propositions, on emploie <em>di</em> + infinitif : <em>penso <b>di</b> avere ragione</em> — « je pense avoir raison ».</p><p><b>Congiuntivo passato</b> : <em>abbia fatto / sia andato</em>, action antérieure à une principale au présent.</p>"
  },
  "ref:g-congiuntivo-imp": {
    title: "Congiuntivo imperfetto et trapassato",
    sub: "concordance des temps et souhaits",
    body: "<p>Imperfetto : radical + <em>-ssi, -ssi, -sse, -ssimo, -ste, -ssero</em> (<em>parlassi, prendessi, dormissi</em>). Irréguliers : <em>essere → fossi</em>, <em>fare → facessi</em>, <em>dare → dessi</em>, <em>stare → stessi</em>, <em>bere → bevessi</em>, <em>dire → dicessi</em>.</p><p class='callout callout--trap'>Attention : le subjonctif imparfait français est un temps mort, réservé à la littérature et souvent ridicule à l'oral (« qu'il vînt »). En italien, il est parfaitement vivant et obligatoire. Le réflexe français de l'éviter conduit directement à l'erreur.</p><h4>Concordance des temps</h4><div class='table-wrap'><table class='gt'><thead><tr><th>principale</th><th>simultané</th><th>antérieur</th></tr></thead><tbody><tr><td>présent</td><td class='it'>congiuntivo presente</td><td>congiuntivo passato</td></tr><tr><td>passé</td><td class='it'>congiuntivo imperfetto</td><td>congiuntivo trapassato</td></tr></tbody></table></div><p><em>Penso che <b>sia</b> partito</em> → <em>Pensavo che <b>fosse</b> partito.</em> Le français moderne remonte au présent (« je pensais qu'il soit parti » ne se dit pas, on dit « qu'il était parti ») ; l'italien applique la règle jusqu'au bout.</p><h4>Le subjonctif de souhait</h4><p>Seul, sans principale : <em>Piovesse almeno!</em>, <em>Magari venisse!</em>, <em>Non l'avessi mai detto!</em>, <em>Volesse il cielo!</em> — le « si seulement il venait ! » français, avec la même charge.</p><p>En <b>C1</b>, ajoute le subjonctif dans une subordonnée antéposée (<em>Che gli italiani fossero un popolo creativo, lo sapevano tutti</em>) et après les noms d'opinion et de sentiment (<em>il dubbio che, la speranza che, l'ipotesi che</em>).</p>"
  },
  "ref:g-periodo-ipotetico": {
    title: "Les phrases hypothétiques",
    sub: "trois types avec se",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>type</th><th>proposition en se</th><th>principale</th></tr></thead><tbody><tr><td>1. réel</td><td class='it'>se + indicatif</td><td>indicatif / impératif</td></tr><tr><td>2. possible</td><td class='it'>se + cong. imperfetto</td><td>conditionnel présent</td></tr><tr><td>3. irréel</td><td class='it'>se + cong. trapassato</td><td>conditionnel passé</td></tr></tbody></table></div><ul><li><em>Se piove, resto a casa.</em></li><li><em>Se avessi tempo, verrei con te.</em></li><li><em>Se avessi studiato, avrei passato l'esame.</em></li></ul><p class='callout callout--trap'>C'est le chapitre où le français induit le plus en erreur. « Si j'avais le temps » emploie un <b>imparfait de l'indicatif</b> ; l'italien exige le <b>subjonctif imparfait</b>, <em>se avessi tempo</em>. Et « si j'avais eu » est un plus-que-parfait de l'indicatif, alors que l'italien met le subjonctif plus-que-parfait, <em>se avessi avuto</em>. La structure des trois types est identique, mais le mode de la subordonnée ne l'est pas.</p><p>En revanche, l'interdit est le même dans les deux langues : jamais de conditionnel après <b>se</b>. « Se avrei » est aussi fautif que « si j'aurais », et le réflexe est déjà en place.</p><p>Les types mixtes sont fréquents : <em>Se avessi studiato, adesso lavorerei qui.</em> À l'oral on entend le double imparfait : <em>Se lo sapevo, non venivo</em> — acceptable en parlant, pas à l'écrit, exactement comme en français.</p>"
  },
  "ref:g-imperativo": {
    title: "L'impératif",
    sub: "tu, Lei, noi, voi et la forme négative",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>personne</th><th>-are</th><th>-ere</th><th>-ire</th></tr></thead><tbody><tr><td>tu</td><td class='it'>parla</td><td>prendi</td><td>senti</td></tr><tr><td>Lei</td><td class='it'>parli</td><td>prenda</td><td>senta</td></tr><tr><td>noi</td><td class='it'>parliamo</td><td>prendiamo</td><td>sentiamo</td></tr><tr><td>voi</td><td class='it'>parlate</td><td>prendete</td><td>sentite</td></tr></tbody></table></div><p class='callout callout--trap'><b>Le négatif de tu emploie l'infinitif</b> : <em>non parlare!</em>, <em>non andare!</em>. Le français dit « ne parle pas » avec la même forme qu'à l'affirmative ; ici l'intuition ne sert pas. Les autres personnes prennent simplement non + forme.</p><p>Formes brèves irrégulières de tu : <em>fa' (fai), da' (dai), sta' (stai), va' (vai), di' (dici)</em>. Le pronom qui suit double la consonne : <em>dammi, fallo, dimmi, vattene</em> (sauf <em>gli</em> — <em>digli</em>).</p><p>Les pronoms se soudent aux formes tu/noi/voi (<em>prendilo, andiamoci, ascoltatemi</em>), comme dans « prends-le », mais passent devant la forme de politesse (<em>lo prenda, mi ascolti</em>).</p>"
  },
  "ref:g-gerundio": {
    title: "Gerundio et stare + gerundio",
    sub: "la forme progressive et les propositions implicites",
    body: "<p>Gerundio : <em>-are → -ando</em>, <em>-ere/-ire → -endo</em>. Irréguliers : <em>facendo, dicendo, bevendo, traducendo, ponendo</em>.</p><ul><li><b>stare + gerundio</b> — action en cours, maintenant seulement : <em>Sto lavorando.</em> C'est « je suis en train de travailler », et rien d'autre.</li><li>circonstance : <em>Camminando, ho incontrato Marco.</em> — le gérondif français « en marchant », sans la préposition « en »</li><li>manière : <em>Ho imparato l'italiano guardando film.</em></li><li>cause : <em>Essendo stanco, sono rimasto a casa.</em></li><li>condition : <em>Studiando di più, passeresti l'esame.</em></li></ul><p class='callout callout--trap'>Le français distingue le participe présent (« marchant ») du gérondif (« en marchant ») ; l'italien a une seule forme pour les deux emplois, sans préposition. Et <em>sto lavorando domani</em> ne veut pas dire « je travaille demain » : pour le futur proche, c'est le présent simple.</p><p>Le gerundio exige <b>le même sujet</b> que la principale, comme le gérondif français. Sinon il faut une subordonnée complète.</p><p><b>Gerundio passato</b> (<em>avendo finito</em>) marque l'antériorité : <em>Avendo finito il lavoro, sono uscito.</em></p>"
  },
  "ref:g-infinito": {
    title: "L'infinitif dans la subordonnée",
    sub: "di, a, per + infinitif",
    body: "<p>Quand les deux propositions ont le même sujet, on emploie l'infinitif au lieu d'une proposition en <em>che</em>. Le français fait pareil (« je pense avoir raison »), mais choisit d'autres prépositions, et c'est là qu'est le travail.</p><ul><li><b>di</b> : <em>penso di partire, spero di vederti, ho paura di sbagliare, finire di, smettere di, cercare di</em></li><li><b>a</b> : <em>comincio a capire, imparo a nuotare, riesco a farlo, aiutare a, provare a, continuare a</em></li><li><b>per</b> (but) : <em>studio per imparare</em>, « j'étudie pour apprendre »</li><li>sans préposition après les modaux et après <em>preferire, desiderare, sapere, far fare, lasciare</em></li></ul><p><b>Infinito passato</b> : <em>dopo aver mangiato</em>, <em>dopo essere uscito</em> — obligatoire après <em>dopo</em>, exactement comme « après avoir mangé » en français. Ce point-là se traduit tel quel.</p>"
  },
  "ref:g-passivo": {
    title: "Le passif",
    sub: "essere, venire, andare, si passivante",
    body: "<ul><li><b>essere</b> + participe — le passif général : <em>La lettera è stata scritta da Marco.</em> C'est le passif français avec « être ».</li><li><b>venire</b> + participe — temps simples seulement, insiste sur le déroulement : <em>La legge viene approvata ogni anno.</em> Pas d'équivalent français.</li><li><b>andare</b> + participe — exprime l'<b>obligation</b> : <em>Il modulo va compilato in stampatello</em> = le formulaire doit être rempli. Ce n'est pas un passif ordinaire, et le lire comme tel change le sens.</li><li><b>si passivante</b> — le plus courant à l'oral : <em>Qui si vendono panini</em>, « ici on vend des sandwichs ». Attention : le français passe par « on » avec le verbe au singulier, l'italien accorde avec la chose vendue.</li></ul><p>L'agent est introduit par <em>da</em> : <em>è stato fatto <b>da</b> loro</em>. Seuls les verbes transitifs forment un passif.</p>"
  },
  "ref:g-participio": {
    title: "Participes présent et passé",
    sub: "comme adjectif, nom et verbe",
    body: "<p><b>Participio presente</b> (<em>-ante, -ente</em>) fonctionne rarement comme verbe, souvent comme adjectif ou nom : <em>brillante, insegnante, cantante, dirigente</em>. Le français a les mêmes fossiles (« brillant », « dirigeant »), figés de la même façon. L'emploi verbal survit dans le registre juridique : <em>il denaro <b>derivante</b> dalle offerte sarà investito</em>.</p><p><b>Participio passato</b> en proposition réduite remplace une temporelle ou une causale : <em><b>Prenotato</b> il viaggio, puoi partire tranquillo.</em> <em><b>Finita</b> la riunione, sono uscito.</em> Le participe s'accorde alors avec le nom auquel il se rapporte. Le français connaît la tournure (« la réunion terminée, je suis sorti »), mais place le nom avant le participe : l'italien fait l'inverse.</p><p>Comme adjectif et nom : <em>apprezzato, pentito, il ferito, i laureati</em>.</p>"
  },
  "ref:g-perifrasi": {
    title: "Les périphrases verbales",
    sub: "sto per, va rivisto, ho da fare",
    body: "<ul><li><b>aspectuelles</b> : <em>sto per partire</em> (je suis sur le point de partir), <em>mi accingo a</em>, <em>sono sul punto di</em>, <em>comincio a</em>, <em>continuo a</em>, <em>smetto di</em>, <em>finisco di</em></li><li><b>modales</b> : <em>il compito <b>va</b> rivisto</em> (le devoir est à revoir), <em><b>ho da</b> studiare</em> (j'ai à étudier), <em>c'è da fare</em> — le français a exactement « il y a à faire » et « c'est à revoir »</li><li><b>de gérondif</b> : <em>sta cadendo</em> (il est en train de tomber), <em>va crescendo</em> (le phénomène va croissant, registre écrit) — cette dernière existe telle quelle en français soutenu</li><li><b>causatives</b> : <em>far fare qualcosa a qualcuno</em> (faire faire quelque chose à quelqu'un), <em>lasciar fare</em>. Le calque est parfait, y compris la construction avec <em>a</em>.</li></ul>"
  },
  "ref:g-preposizioni": {
    title: "Prépositions simples et contractées",
    sub: "di, a, da, in, su, con, per, tra/fra",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th></th><th>il</th><th>lo</th><th>la</th><th>l'</th><th>i</th><th>gli</th><th>le</th></tr></thead><tbody><tr><td>di</td><td class='it'>del</td><td>dello</td><td>della</td><td>dell'</td><td>dei</td><td>degli</td><td>delle</td></tr><tr><td>a</td><td class='it'>al</td><td>allo</td><td>alla</td><td>all'</td><td>ai</td><td>agli</td><td>alle</td></tr><tr><td>da</td><td class='it'>dal</td><td>dallo</td><td>dalla</td><td>dall'</td><td>dai</td><td>dagli</td><td>dalle</td></tr><tr><td>in</td><td class='it'>nel</td><td>nello</td><td>nella</td><td>nell'</td><td>nei</td><td>negli</td><td>nelle</td></tr><tr><td>su</td><td class='it'>sul</td><td>sullo</td><td>sulla</td><td>sull'</td><td>sui</td><td>sugli</td><td>sulle</td></tr></tbody></table></div><p>Le français ne contracte que « au / du / aux / des » ; l'italien contracte cinq prépositions avec les sept articles. Le tableau se retient en entier, mais la logique est celle que tu connais.</p><p><em>con</em>, <em>per</em> et <em>tra/fra</em> ne se contractent pas (à part le rare <em>col</em>).</p><h4>Lieu : a ou in</h4><p>Aucune logique transposable depuis le français, qui répartit « à » et « en » autrement. C'est une liste.</p><ul><li><b>a</b> : villes (<em>a Roma</em>), <em>a casa, a scuola, a letto, al mare, al cinema, al lavoro</em></li><li><b>in</b> : pays et régions (<em>in Italia, in Toscana</em>), <em>in centro, in ufficio, in banca, in montagna, in vacanza</em>, moyens de transport (<em>in treno, in macchina</em>)</li><li><b>da</b> : « chez » et « de la part de » (<em>vado dal medico, vengo da Marco</em>) — c'est le « chez » français, qui n'a pas d'équivalent d'un seul mot en italien</li></ul>"
  },
  "ref:g-prep-verbi": {
    title: "Les prépositions imposées par le verbe",
    sub: "une liste qui s'apprend, tout simplement",
    body: "<p>La préposition qui suit un verbe n'est pas logique, elle est lexicale — comme « penser <b>à</b> » et « rêver <b>de</b> » en français. Elle s'apprend avec le verbe, et il ne faut pas supposer qu'elle recoupe la française.</p><h4>+ di</h4><p><em>finire di, smettere di, cercare di, decidere di, dimenticare di, ricordarsi di, accorgersi di, avere bisogno di, avere paura di, pensare di, sperare di, accettare di, promettere di, evitare di</em></p><h4>+ a</h4><p><em>cominciare a, iniziare a, continuare a, imparare a, riuscire a, provare a, aiutare a, insegnare a, abituarsi a, rinunciare a, pensare a (penser à), servire a</em></p><h4>sans préposition</h4><p><em>potere, volere, dovere, sapere, preferire, desiderare, amare, osare, far fare, lasciare, vedere, sentire</em></p><p class='callout callout--trap'>Trois écarts fréquents : <em>sperare di</em> là où le français dit « espérer » sans préposition ; <em>cercare di</em> pour « essayer de » ; et surtout <em>pensare a</em> (penser à quelque chose) contre <em>pensare di</em> (avoir l'intention, ou avoir un avis). <em>Penso a te</em> ≠ <em>Penso di partire</em>.</p>"
  },
  "ref:g-avverbi": {
    title: "Les adverbes",
    sub: "formation, place, adverbes de portée",
    body: "<p>À partir de l'adjectif : forme féminine + <em>-mente</em>, exactement le mécanisme de « lente → lentement ». Les adjectifs en <em>-le/-re</em> perdent le e : <em>facile → facilmente</em>, <em>regolare → regolarmente</em>.</p><p><b>Place</b> : les adverbes de fréquence se mettent juste après le verbe conjugué (<em>vado <b>spesso</b> al cinema</em>), comme « je vais souvent ». Aux temps composés, <em>già, mai, ancora, sempre, appena</em> se placent <b>entre l'auxiliaire et le participe</b> : <em>ho <b>già</b> mangiato</em>, <em>non sono <b>mai</b> stato</em> — la même place qu'en français, « j'ai déjà mangé ». Ce point se transpose sans réfléchir.</p><p><b>Adverbes de portée</b> (B2) : <em>anche, pure, solo, soltanto, perfino, addirittura, soprattutto, specialmente, proprio, neanche, nemmeno, neppure</em> : le sens change selon ce qu'ils précèdent.</p><p><b>Buono/bene</b> : <em>buono</em> est l'adjectif, <em>bene</em> l'adverbe, le couple « bon / bien ». <em>Un caffè buono</em> face à <em>parla bene</em>.</p>"
  },
  "ref:g-connettivi": {
    title: "Les connecteurs de texte",
    sub: "ce qui tient un discours ou une dissertation",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>fonction</th><th>connecteurs</th></tr></thead><tbody><tr><td>ajouter</td><td class='it'>inoltre, in più, anche, per di più, oltre a ciò</td></tr><tr><td>opposer</td><td class='it'>però, tuttavia, invece, al contrario, anzi, d'altra parte, nondimeno</td></tr><tr><td>cause</td><td class='it'>perché, poiché, siccome, dato che, visto che, in quanto</td></tr><tr><td>conséquence</td><td class='it'>quindi, perciò, dunque, di conseguenza, pertanto</td></tr><tr><td>explication</td><td class='it'>cioè, ovvero, vale a dire, in altre parole, in effetti</td></tr><tr><td>ordre</td><td class='it'>anzitutto, in primo luogo, in secondo luogo, infine, per concludere</td></tr><tr><td>résumé</td><td class='it'>insomma, in conclusione, tutto sommato</td></tr></tbody></table></div><p>Le français scolaire a la même boîte à outils (« en outre », « toutefois », « par conséquent »), et la dissertation italienne attend la même architecture explicite. Tu réutilises ta méthode, tu changes les mots.</p><p><b>Marqueurs du discours</b> à l'oral : <em>ecco, allora, niente, insomma, no?, vedi, capirai, guarda, senti, dai</em>. Ils n'apportent pas de contenu, mais sans eux on a l'air de lire — l'équivalent de « bon », « enfin », « voilà », « quoi ».</p>"
  },
  "ref:g-frase": {
    title: "Ordre des mots, questions, négation",
    sub: "comment se bâtit une phrase",
    body: "<p>Ordre de base : <b>sujet – verbe – objet</b>, le sujet étant en général omis.</p><p><b>Les questions</b> ne changent pas l'ordre des mots : l'intonation ou un mot interrogatif suffit. <em>Parli italiano?</em>, <em>Dove abiti?</em> Pas d'inversion, pas d'« est-ce que » : l'italien n'a rien qui corresponde à cette béquille française, et il ne faut pas chercher à la fabriquer.</p><p><b>Négation</b> : <em>non</em> devant le verbe, et c'est tout — il n'y a pas de second élément. Là où le français encadre avec « ne… pas », l'italien met un seul mot. En revanche la double négation est correcte et obligatoire : <em>Non ho <b>mai</b> visto <b>niente</b> di simile</em>, comme « je n'ai jamais rien vu de tel ». Quand le mot négatif précède le verbe, <em>non</em> disparaît : <em><b>Nessuno</b> è venuto.</em></p><p>Interrogatifs : <em>chi, che cosa, dove, quando, come, perché, quale, quanto</em>. Attention à <em>dov'è</em>, <em>com'è</em>, <em>qual è</em> (ce dernier sans apostrophe).</p>"
  },
  "ref:g-discorso-indiretto": {
    title: "Le discours indirect",
    sub: "décalage des temps et des repères",
    body: "<div class='table-wrap'><table class='gt'><thead><tr><th>discours direct</th><th>indirect (après un passé)</th></tr></thead><tbody><tr><td>presente</td><td class='it'>imperfetto</td></tr><tr><td>passato prossimo / remoto</td><td class='it'>trapassato prossimo</td></tr><tr><td>futuro</td><td class='it'>condizionale passato</td></tr><tr><td>imperativo</td><td class='it'>di + infinito</td></tr><tr><td>congiuntivo presente</td><td class='it'>congiuntivo imperfetto</td></tr></tbody></table></div><p>Les repères de temps et de lieu se décalent aussi : <em>oggi → quel giorno, domani → il giorno dopo, ieri → il giorno prima, qui → lì, questo → quello, adesso → allora</em>. Le français fait exactement pareil.</p><p class='callout callout--trap'><em>« Verrò domani » → Disse che <b>sarebbe venuto il giorno dopo</b>.</em> Voilà la seule vraie divergence : le français dit « il a dit qu'il viendrait » avec un conditionnel présent, l'italien exige le <b>conditionnel passé</b>. C'est l'erreur la plus tenace du chapitre.</p>"
  },
  "ref:g-registri": {
    title: "Registres et style",
    sub: "formel, familier, administratif",
    body: "<p><b>Italien formel</b> : le passif, les nominalisations (<em>l'approvazione della legge</em>), <em>Lei</em>, un lexique latinisant (<em>effettuare</em> plutôt que <em>fare</em>), l'évitement des verbes pronominaux.</p><p><b>Italien parlé / neostandard</b> : <em>lui/lei</em> comme sujet, <em>gli</em> pour <em>loro</em>, <em>che</em> passe-partout (<em>il giorno che sono arrivato</em>), dislocation (<em>il libro, l'ho letto</em>), imperfetto à la place du subjonctif dans les hypothétiques.</p><p><b>Burocratese</b> : <em>di cui sopra, ai sensi di, in ottemperanza a, si comunica che, il sottoscritto</em>. En C1, savoir le <i>lire</i> compte plus que savoir l'écrire. L'administration française cultive les mêmes travers et mène les mêmes campagnes de simplification.</p><p><b>La dislocation</b> comme outil : <em>A Roma non ci sono mai stato</em> déplace le poids informatif en tête de phrase. Ce n'est pas du relâchement, c'est le fonctionnement de l'italien vivant — et le français oral fait exactement pareil : « à Rome, j'y suis jamais allé ».</p>"
  },
  "ref:g-fonologia": {
    title: "Prononciation et orthographe",
    sub: "c, g, gl, gn, consonnes doubles, accent",
    body: "<p>La bonne nouvelle d'abord : l'orthographe italienne est régulière. Une fois les règles connues, n'importe quel mot se lit correctement — rien à voir avec le français et ses lettres muettes.</p><h4>C et G</h4><p>Devant <em>a, o, u</em> elles sont dures : <em>casa, gatto</em>. Devant <em>e, i</em> elles s'adoucissent, mais <b>pas comme en français</b> : <em>cena</em> se dit « tchéna » et non « séna », <em>gelato</em> se dit « djélato » et non « jélato ». Un <b>h</b> rétablit le son dur : <em>chiesa</em> (« kiéza »), <em>ghiaccio</em>. Un <b>i</b> adoucit sans se prononcer : <em>ciao</em> (« tchao »), <em>giorno</em> (« djorno »).</p><h4>Groupes particuliers</h4><ul><li><b>gn</b> = le gn français de « agneau » : <em>gnocchi, bagno, signore</em> — identique, rien à apprendre</li><li><b>gl</b> + i = un son que le français n'a pas, proche du « ill » de « famille » : <em>famiglia, figlio, aglio</em> ; mais <em>glicine, negligente</em> se lisent g+l</li><li><b>sc</b> devant e/i = « ch » français : <em>pesce, sciare</em> ; devant a/o/u = sk : <em>scala, scuola</em></li><li><b>z</b> = ts ou dz : <em>pizza</em> (« pitsa »), <em>zero</em> (« dzéro »)</li><li>toutes les voyelles finales se prononcent : <em>parle</em> ≠ <em>parla</em>, et le e final n'est jamais muet</li></ul><h4>Consonnes doubles</h4><p>Elles s'entendent et changent le sens : <em>casa</em> (maison) / <em>cassa</em> (caisse), <em>pala</em> (pelle) / <em>palla</em> (balle), <em>nono</em> (neuvième) / <em>nonno</em> (grand-père). Le français écrit des doubles sans les prononcer, ce qui en fait l'habitude la plus difficile à prendre : il faut vraiment <b>tenir la consonne</b>.</p><h4>L'accent</h4><p>D'ordinaire sur l'avant-dernière syllabe. L'italien accentue les mots ; le français accentue les groupes, en fin de groupe. C'est ce déplacement d'accent, plus que les sons, qui trahit un francophone. L'accent écrit final est obligatoire : <em>città, perché, caffè, così, più</em>. Attention aux mots accentués sur l'antépénultième : <em><b>abi</b>tano, <b>tele</b>fono, <b>por</b>tami</em>.</p>"
  }
});
